/// <summary>
/// designed from AVA
/// </summary>
public void init()
{
    next init();
    if (!xUserInfo::checkUserOrAdminRole('AVAWorkPreparationProdReports'))
    {
        this.design().controlName(formControlStr(ProdParmStartup,   AVAPrintProdProdOrderOptions)).visible(false);
        this.design().controlName(formControlStr(ProdParmStartup,   AVAPrintProdRunMapOptions)).visible(false);
    }
}
